declare(strict_types=1); require_once __DIR__.'/product_auth.php'; $pdo=db();$id=(int)($_GET['id']??0);$s=$pdo->prepare('SELECT * FROM products WHERE id=?');$s->execute([$id]);$p=$s->fetch();if(!$p){http_response_code(404);exit('Product not found.');}$pageTitle='Product Details';require __DIR__.'/header.php';?><div class="card"><h1>Product Details</h1><p><strong>ID:</strong> <?= (int)$p['id'] ?></p><p><strong>SKU:</strong> <?= e($p['sku']) ?></p><p><strong>Name:</strong> <?= e($p['name']) ?></p><p><strong>Price:</strong> <?= number_format((float)$p['price'],2) ?></p><p><strong>Description:</strong><br><?= nl2br(e($p['description'])) ?></p><p><strong>Created:</strong> <?= e($p['created_at']) ?></p><p><strong>Updated:</strong> <?= e($p['updated_at']) ?></p><a class="button" href="product_edit.php?id=<?= (int)$p['id'] ?>">Edit</a><a class="button secondary" href="products.php">Back</a></div><?php require __DIR__.'/footer.php'; ?>
